def grep(pattern, flags, files):
    flag_list = flags.split()

    n = '-n' in flag_list
    l = '-l' in flag_list
    i = '-i' in flag_list
    v = '-v' in flag_list
    x = '-x' in flag_list

    results = []

    for file_name in files:
        file_matches = []
        with open(file_name, 'r') as f:
            lines = f.readlines()

        for idx, line in enumerate(lines):
            line_content = line.rstrip('\n')

            # Match logic
            p = pattern.lower() if i else pattern
            l_c = line_content.lower() if i else line_content

            if x:
                match = (p == l_c)
            else:
                match = (p in l_c)

            if v:
                match = not match

            if match:
                file_matches.append((idx + 1, line_content))

        if file_matches:
            if l:
                results.append(f"{file_name}\n")
            else:
                for line_num, content in file_matches:
                    res = ""
                    if len(files) > 1:
                        res += f"{file_name}:"
                    if n:
                        res += f"{line_num}:"
                    res += f"{content}\n"
                    results.append(res)

    return "".join(results)
